async function countByTeamId(teamId, options = {}) {
  return Player.count({
    where: { team_id: teamId },
    ...options
  });
}

module.exports = {
  findById,
  findByIdForUpdate,
  findByName,
  findByExactName,
  save,
  findFreePlayers,
  findTakenPlayers,
  countByTeamId
